sp_page.css:
$banner-768-svg : "d9bc1319533130101865ddeeff7b12ba.iix";


/*main.body {
  padding-top: 0rem !important;
 	overflow-y: auto;
	height: 100%;
}
*/


/* Padding for container after banner image */
.padding-top {
  padding-top: 2.4rem;
}

/* Padding bottom after each widget */
.child-b-margin > span > div > *{
  margin-bottom: 2.4rem;
}



.mobile-banner {
  background-position: right bottom !important;
}

/* Max width for Containers to stay in view port*/
.container {
  max-width: default;
}

@media (max-width: 48em) {
  .ng-scope.mobile-banner {
    background-image:url($banner-768-svg) !important;
    background-repeat: no-repeat;
    background-size: 100rem;
  }
  .child-b-margin > span > div > *{
    margin-bottom: 1.6rem;
  }
  .padding-right {
    padding-right: 0rem;
  }
   .padding-top {
    padding-top: 1.6rem;
  }
}

@media (max-width : 62em) {
  .container {
    width : 100%;
  }
  .col-md-4 {
    width : 100%
  }
  .col-md-8 {
    width : 100%
  }
  .left-column{
    padding-left: 2.4rem;
    padding-right: 2.4rem;  
  } 
  .right-column{
    padding-left: 2.4rem;
    padding-right: 2.4rem;  
  }
}

@media (min-width: 62em) {  
  .container {  
    padding-left: 1.2rem;   
    padding-right: 1.2rem;  
  } 
  .left-column{
    padding-right: 0rem;    
  } 
  .right-column{
    padding-left: 2.4rem;
    padding-right: 1.6rem;
  } 
}

.imagem-sefaz-home{
  background-size: cover;
  background-position: center;
  min-height: 300px;
  position: relative; /* ou static */
  z-index: 1;
  //margin-top: 16rem;
}
